import{_ as e,o as a,c as i,a3 as s}from"./chunks/framework.BTt0kA_k.js";const r="/RelayPulse/screenshots/user/notifications-settings.webp",o="/RelayPulse/screenshots/user/notification-template.webp",_=JSON.parse('{"title":"消息通知","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/notifications.md","filePath":"user/use/notifications.md"}'),l={name:"user/use/notifications.md"};function n(c,t,d,p,h,u){return a(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="消息通知" tabindex="-1">消息通知 <a class="header-anchor" href="#消息通知" aria-label="Permalink to &quot;消息通知&quot;">​</a></h1><p>入口：<strong>配置 → 消息通知</strong>。目前通过操作系统显示通知，规则包括模型探测故障、模型探测恢复和智商测试完成。</p><h2 id="授权系统通知" tabindex="-1">授权系统通知 <a class="header-anchor" href="#授权系统通知" aria-label="Permalink to &quot;授权系统通知&quot;">​</a></h2><ol><li>打开“启用消息通知”。</li><li>查看“系统通知”一行的权限状态。</li><li>显示“尚未授权”或“状态未知”时，点击“请求授权”，按 macOS 提示选择。</li><li>显示“已授权”后，点击“发送测试通知”确认能否收到。</li></ol><p>显示“已拒绝”时，点击“去系统设置”，在 macOS 通知设置中允许 RelayPulse 通知。仍未显示时，检查系统通知样式、专注模式和勿扰设置。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/notifications-settings.webp"><img src="'+r+'" alt="消息通知页面中已授权的系统通知及故障恢复和测试完成规则"></a></p><figcaption>① 通知总开关与系统权限状态；② 各事件规则的开关和模板编辑入口。本图展示已授权状态。</figcaption></figure><h2 id="选择接收哪些事件" tabindex="-1">选择接收哪些事件 <a class="header-anchor" href="#选择接收哪些事件" aria-label="Permalink to &quot;选择接收哪些事件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>触发时机</th></tr></thead><tbody><tr><td>模型探测故障</td><td>模型达到稳定故障判定时</td></tr><tr><td>模型探测恢复</td><td>模型从稳定故障恢复时</td></tr><tr><td>智商测试完成</td><td>整场测试结束后通知一次，包含有失败结果的测试</td></tr></tbody></table><p>在规则行切换启用开关。故障、恢复规则依据<a href="./probes.html#健康状态怎样判定">健康阈值</a>触发；单次请求失败不一定立即发送故障通知，偏慢也不等同于故障。</p><p>关闭通知总开关会保留规则配置，同时停止发送通知。</p><h2 id="自定义通知模板" tabindex="-1">自定义通知模板 <a class="header-anchor" href="#自定义通知模板" aria-label="Permalink to &quot;自定义通知模板&quot;">​</a></h2><ol><li>点击规则行的编辑图标，打开“编辑通知模板”。</li><li>切换到“自定义模板”。</li><li>选择标题标记，编辑标题和通知详情。</li><li>通过“插入变量”菜单插入该模板可用的变量。</li><li>检查下方通知预览，必要时点击“测试当前模板”。</li><li>点击“保存”。</li></ol><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/notification-template.webp"><img src="'+o+'" alt="编辑通知模板，切换自定义模板并编辑标题详情、插入变量和查看预览"></a></p><figcaption>① 切换到自定义模板；② 插入事件变量。下方预览用于检查最终显示内容，编辑后需保存。</figcaption></figure><p>标题最多 <strong>120 个显示字符</strong>，详情最多 <strong>500 个显示字符</strong>，以界面的计数和校验结果为准。预览使用固定示例数据。</p><p>“测试当前模板”会实际发送测试通知，但不会替你保存模板；确认内容后仍需点击“保存”。需要还原时，使用“恢复默认”并保存。</p><p>当前渠道为系统通知；页面没有配置邮件、Webhook 或聊天机器人渠道的入口。</p>',16)])])}const g=e(l,[["render",n]]);export{_ as __pageData,g as default};
